class Solution {
public:
    int maximumSum(vector<int>& nums) {
        int largest[82];
        for (int i = 0; i < 82; ++i) largest[i] = -1;
        int ans = -1;
        for (int x : nums) {
            int s = 0, t = x;
            while (t > 0) {
                s += t % 10;
                t /= 10;
            }
            if (largest[s] != -1) {
                int cand = x + largest[s];
                if (cand > ans) ans = cand;
            }
            if (x > largest[s]) largest[s] = x;
        }
        return ans;
    }
};
